Theorem possible_bag_functional_rel_equiv
    (T : Tuple.Rcd) (left right : SqlBagAbstraction.bagT T -> Prop) :
  rel_equiv left right ->
  @possible_bag_functional T left ->
  @possible_bag_functional T right.

Theorem query_success_bags_functional_of_unary_reset
    (T : Tuple.Rcd) (parent_bags input_bags : SqlBagAbstraction.bagT T -> Prop)
    (operation : unary_bag_relation T) :
  rel_equiv parent_bags (lift_possible_bag_unary operation input_bags) ->
  unary_bag_relation_extensional operation ->
  @unary_bag_relation_functional T operation ->
  @possible_bag_functional T input_bags ->
  @possible_bag_functional T parent_bags.

Theorem query_success_bags_functional_of_binary_reset
    (T : Tuple.Rcd)
    (parent_bags left_bags right_bags : SqlBagAbstraction.bagT T -> Prop)
    (operation : binary_bag_relation T) :
  rel_equiv parent_bags
    (lift_possible_bag_binary operation left_bags right_bags) ->
  binary_bag_relation_extensional operation ->
  @binary_bag_relation_functional T operation ->
  @possible_bag_functional T left_bags ->
  @possible_bag_functional T right_bags ->
  @possible_bag_functional T parent_bags.

Lemma query_same_rows_as_bag_permut_between :
  forall (T : Tuple.Rcd) first second bag,
    @query_same_rows_as_bag T first bag ->
    @query_same_rows_as_bag T second bag ->
    Oeset.permut (OTuple T) first second.

Theorem query_make_groups_group_terms_Permutation :
  forall (T : Tuple.Rcd) (env : Env.env T) rows left_terms right_terms,
    Sorting.Permutation.Permutation left_terms right_terms ->
    @query_make_groups T env rows left_terms =
    @query_make_groups T env rows right_terms.

Theorem query_make_groups_global_exact :
  forall (T : Tuple.Rcd) (env : Env.env T) rows,
    @query_make_groups T env rows [] = [rev rows].

Lemma exact_sum_aggregate_permutation :
  forall function left right,
    In function
      [Aggregate AggregateSumInt32;
       DistinctAggregate AggregateSumInt32;
       Aggregate AggregateSumInt64Numeric;
       DistinctAggregate AggregateSumInt64Numeric;
       Aggregate AggregateSumNumeric;
       DistinctAggregate AggregateSumNumeric] ->
    Permutation left right ->
    interp_aggregate function left = interp_aggregate function right.

Lemma exact_sum_runtime_error_permutation :
  forall function left right,
    In function
      [Aggregate AggregateSumInt32;
       DistinctAggregate AggregateSumInt32;
       Aggregate AggregateSumInt64Numeric;
       DistinctAggregate AggregateSumInt64Numeric;
       Aggregate AggregateSumNumeric;
       DistinctAggregate AggregateSumNumeric] ->
    Permutation left right ->
    aggregate_local_runtime_error function left =
    aggregate_local_runtime_error function right.

Lemma fixed_numeric_aggregate_permutation :
  forall precision scale function left right,
    In function
      [Aggregate (AggregateStddevSampleNumericFixed precision scale);
       DistinctAggregate (AggregateStddevSampleNumericFixed precision scale);
       Aggregate (AggregateAverageNumericFixed precision scale);
       DistinctAggregate (AggregateAverageNumericFixed precision scale)] ->
    Permutation left right ->
    interp_aggregate function left = interp_aggregate function right.

Lemma fixed_numeric_aggregate_runtime_error_permutation :
  forall precision scale function left right,
    In function
      [Aggregate (AggregateStddevSampleNumericFixed precision scale);
       DistinctAggregate (AggregateStddevSampleNumericFixed precision scale);
       Aggregate (AggregateAverageNumericFixed precision scale);
       DistinctAggregate (AggregateAverageNumericFixed precision scale)] ->
    Permutation left right ->
    aggregate_local_runtime_error function left =
    aggregate_local_runtime_error function right.

Lemma integral_numeric_aggregate_permutation :
  forall function left right,
    In function
      [Aggregate AggregateAverageInt32Numeric;
       DistinctAggregate AggregateAverageInt32Numeric;
       Aggregate (AggregateNumericDisplayScale NumericAverageInt32);
       Aggregate (AggregateNumericDisplayScale NumericStddevSampleInt32);
       Aggregate AggregateAverageInt64Numeric;
       DistinctAggregate AggregateAverageInt64Numeric;
       Aggregate AggregateVariancePopulationInt32;
       DistinctAggregate AggregateVariancePopulationInt32;
       Aggregate AggregateVarianceSampleInt32;
       DistinctAggregate AggregateVarianceSampleInt32;
       Aggregate AggregateStddevPopulationInt32;
       DistinctAggregate AggregateStddevPopulationInt32;
       Aggregate AggregateStddevSampleInt32;
       DistinctAggregate AggregateStddevSampleInt32] ->
    Permutation left right ->
    interp_aggregate function left = interp_aggregate function right.

Lemma declare_local_query_schemas_basesort_extensional :
  forall schemas first second,
    (forall relation,
      @_basesort TNull first relation =S=
      @_basesort TNull second relation) ->
    forall relation,
      @_basesort TNull (declare_local_query_schemas first schemas) relation =S=
      @_basesort TNull (declare_local_query_schemas second schemas) relation.

Lemma bound_query_admissible_database_shape_extensional :
  forall schemas first second query,
    @_relnames TNull first = @_relnames TNull second ->
    (forall relation,
      @_basesort TNull first relation =S=
      @_basesort TNull second relation) ->
    bound_query_admissible first schemas query ->
    bound_query_admissible second schemas query.

Lemma bound_query_program_admissible_database_shape_extensional :
  forall schemas first second program,
    @_relnames TNull first = @_relnames TNull second ->
    (forall relation,
      @_basesort TNull first relation =S=
      @_basesort TNull second relation) ->
    bound_query_program_admissible first schemas program ->
    bound_query_program_admissible second schemas program.

Lemma query_same_rows_as_bag_filter_length_between :
  forall keep first second bag,
    tuple_predicate_proper keep ->
    @query_same_rows_as_bag TNull first bag ->
    @query_same_rows_as_bag TNull second bag ->
    List.length (filter keep first) = List.length (filter keep second).

Lemma query_expr_admissible_with_outputs_values :
  forall (outputs : list (attribute T)) rows,
    @query_output_attributes_unique T outputs ->
    @query_values_well_sorted T (@query_outputs_sort T outputs) rows ->
    query_expr_admissible_with_outputs
      (@QExpr_Values T generic_relname outputs rows) outputs.

Lemma query_expr_admissible_with_outputs_table :
  forall (outputs : list (attribute T)) table,
    @query_output_attributes_unique T outputs ->
    @query_outputs_sort T outputs =S= basesort table ->
    query_expr_admissible_with_outputs
      (@QExpr_Table T generic_relname outputs table) outputs.

Lemma query_canonical_rows_same_as_bag :
  forall (T : Tuple.Rcd) rows bag,
    @query_same_rows_as_bag T rows bag ->
    @query_same_rows_as_bag T (@query_canonical_rows T rows) bag.

Lemma query_canonical_rows_length_between :
  forall (T : Tuple.Rcd) first second bag,
    @query_same_rows_as_bag T first bag ->
    @query_same_rows_as_bag T second bag ->
    List.length (@query_canonical_rows T first) =
    List.length (@query_canonical_rows T second).

Lemma query_row_output_values_congr :
  forall outputs left right,
    query_row_has_outputs outputs left ->
    Oeset.compare (OTuple T) left right = Eq ->
    @query_row_output_values T outputs left =
    @query_row_output_values T outputs right.

Lemma query_same_rows_as_bag_empty_decision :
  forall first second bag,
    @query_same_rows_as_bag T first bag ->
    @query_same_rows_as_bag T second bag ->
    rows_empty_decision first = rows_empty_decision second.
